import { SlotReels } from "@/components/design-for-ai/text-slot-reels";

// Change value and every character that differs spins into place.
<h2 className="font-display text-7xl tracking-tight">
  <SlotReels value={release.codename} announce />
</h2>

// Figures pad on the left, so a growing number keeps its digits aligned.
<p className="font-mono tabular-nums">
  MRR <SlotReels value={formatUsd(mrr)} stagger={30} duration={700} />
</p>

<SlotReels value="Sold out" direction="down" spins={2} replayKey={launchId} />
